def find_all_paths_through_comp(grid, start_cell, h, w):
    """Find how many ways you can enter/exit a component through its boundary"""
    r0, c0 = start_cell

    # Find the component containing start
    visited = {start_cell}
    comp = [start_cell]
    queue = deque([start_cell])

    while queue:
        r,c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and (nr,nc) not in visited:
                visited.add((nr,nc))
                comp.append((nr,nc))
                queue.append((nr,nc))

    # Now count entry points (cells where you can reach this component from outside)
    entry_points = set()
